mapper.sql:
WHERE wo.deleted = 0
AND wo.owner_id = #{scope.ownerId}

    AND (wo.accepted_worker_id = #{scope.workerId}
    OR wo.assigned_worker_id = #{scope.workerId})

AND wo.id = #{scope.orderId}
AND wo.order_no = #{scope.orderNo}
AND u.real_name = #{scope.workerName}

    AND wo.status IN

        #{status}


AND  >= #{scope.from}
AND  < #{scope.to}

FROM maintenance_worker mw
JOIN `user` u ON u.id = mw.user_id AND u.deleted = 0 AND u.status = 1

LEFT JOIN (
    SELECT assigned_worker_id, COUNT(*) AS pending
    FROM work_order
    WHERE deleted = 0 AND status = 'ASSIGNED' AND assigned_worker_id IS NOT NULL
    GROUP BY assigned_worker_id
) assigned ON assigned.assigned_worker_id = mw.id
WHERE mw.deleted = 0 AND mw.audit_status = #{scope.auditPassed}
  AND mw.work_status != #{scope.disabled}

AND mw.current_load = 0
AND assigned.pending IS NULL
AND mw.work_status = #{scope.workStatus}
